function getNestedEntriesByKey(targetOption, keyString) {
    // Split the key string into individual keys based on dots
    const keys = keyString.split('.');

    let currentKey = targetOption;

    for (let i = 0; i < keys.length; i++) {
        // If the current key doesn't exist or it's not an object, stop looking.
        if (!(currentKey && typeof currentKey === 'object' && currentKey.hasOwnProperty(keys[i]))) {
            break;
        }

        // Move to the next level of nesting
        currentKey = currentKey[keys[i]];
    }

    return currentKey || [];
}

